import { useState, useRef } from "react";
import { useNavigate } from "react-router-dom";
import { useDispatch } from "react-redux";
import { Box, Button, TextField, Typography, useTheme } from "@mui/material";
import EditOutlinedIcon from "@mui/icons-material/EditOutlined";
import ErrorIcon from "@mui/icons-material/Error";
import { Formik } from "formik";
import * as yup from "yup";
import Dropzone from "react-dropzone";
import FlexBetween from "components/FlexBetween";
import { setLogin } from "state";
import ReportIcon from "@mui/icons-material/Report";

const registerSchema = yup.object().shape({
  name: yup.string().required("required"),
  phone: yup.string().required("required"),
  password: yup.string().required("required"),
  passwordVerify: yup.string().required("required"),
  code: yup.string().required("required"),
  passcode: yup.string(),
  picture: yup.string(),
});

const loginSchema = yup.object().shape({
  name: yup.string(),
  phone: yup.string().required("required"),
  password: yup.string().required("required"),
});

const initialValuesRegister = {
  name: "",
  phone: "",
  password: "",
  passwordVerify: "",
  code: "",
  passcode: "",
  picture: "",
};

const initialValuesLogin = {
  name: "",
  phone: "",
  password: "",
};

const LoginPage = () => {
  const [sentCode, setSentCode] = useState(false);

  const [pageType, setPageType] = useState("login");
  const { palette } = useTheme();
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const isLogin = pageType === "login";
  const isRegister = pageType === "register";

  const form = useRef();

  const register = async (values, onSubmitProps) => {
    // if (values.passcode !== values.code) {
    //   alert("승인코드가 일치하지 않습니다.");
    //   values.code = "";
    //   return;
    // }

    if (values.password !== values.passwordVerify) {
      alert("password가 일치하지 않습니다.");
      return;
    }

    const formData = new FormData();
    for (let value in values) {
      formData.append(value, values[value]);
    }

    if (values.picture !== undefined) {
      formData.append("picturePath", values.picture.name);
    } else {
      formData.append("picturePath", "profile.jpg");
    }

    const response = await fetch("http://3.37.116.103:3500/auth/register", {
      method: "POST",
      body: formData,
    });

    if (!response.ok) {
      const error = await response.json();
      alert(error);
      onSubmitProps.resetForm();
      return;
    }

    const savedUser = await response.json();
    onSubmitProps.resetForm();

    if (savedUser) {
      setPageType("login");
    }
  };

  const login = async (values, onSubmitProps) => {
    try {
      const response = await fetch("http://3.37.116.103:3500/auth/login", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(values),
      });

      if (!response.ok) {
        const error = await response.json();
        alert(error);
        return;
      }

      const loggedIn = await response.json();
      onSubmitProps.resetForm();

      dispatch(
        setLogin({
          user: loggedIn.user,
          token: loggedIn.token,
        }),
      );
      navigate("/registsales");
    } catch (error) {
      alert(error.message);
    }
  };

  const handleFormSubmit = async (values, onSubmitProps) => {
    if (isLogin) await login(values, onSubmitProps);
    if (isRegister) await register(values, onSubmitProps);
  };

  const sendSMS = async (values, setFieldValue) => {
    if (values.name === "" || values.phone === "") {
      alert("이름과 전화번호를 먼저 입력하세요");
      return;
    }

    const response = await fetch("http://3.37.116.103:3500/auth/sendSMS", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ phone: values.phone }),
    });

    if (!response.ok) {
      const error = await response.json();
      alert(error);
      return;
    }

    const code = await response.json();
    setFieldValue("passcode", code.code);
    setSentCode(true);

    alert("승인 code가 전송되었습니다.");
  };

  const inputPhoneNumber = (setFieldValue, e) => {
    const value = e.target.value.replace(/\D/g, ""); // 숫자만 추출
    let formattedValue = "";

    if (value.length < 4) {
      formattedValue = value;
    } else if (value.length < 8) {
      formattedValue = value.replace(/(\d{3})(\d{1,4})/, "$1-$2");
    } else if (value.length < 12) {
      formattedValue = value.replace(/(\d{3})(\d{4})(\d{1,4})/, "$1-$2-$3");
    } else {
      formattedValue = value
        .slice(0, 11)
        .replace(/(\d{3})(\d{4})(\d{1,4})/, "$1-$2-$3");
    }

    setFieldValue("phone", formattedValue);
  };

  return (
    <Formik
      onSubmit={handleFormSubmit}
      initialValues={isLogin ? initialValuesLogin : initialValuesRegister}
      validationSchema={isLogin ? loginSchema : registerSchema}
    >
      {({
        values,
        errors,
        touched,
        handleBlur,
        handleChange,
        handleSubmit,
        setFieldValue,
        resetForm,
      }) => (
        <form ref={form} onSubmit={handleSubmit}>
          <Box display="grid" gap="10px">
            {isRegister && (
              <>
                <TextField
                  label="이름*"
                  onBlur={handleBlur}
                  onChange={handleChange}
                  value={values.name}
                  name="name"
                  error={Boolean(touched.name) && Boolean(errors.name)}
                  helperText={touched.name && errors.name}
                />
                <Box
                  border={`1px solid ${palette.neutral.medium}`}
                  borderRadius="5px"
                  p="1rem"
                >
                  <Dropzone
                    acceptedFiles=".jpg,.jpeg,.png"
                    multiple={false}
                    onDrop={(acceptedFiles) =>
                      setFieldValue("picture", acceptedFiles[0])
                    }
                  >
                    {({ getRootProps, getInputProps }) => (
                      <Box
                        {...getRootProps()}
                        border={`2px dashed ${palette.primary.main}`}
                        p="1rem"
                        sx={{ "&:hover": { cursor: "pointer" } }}
                      >
                        <input {...getInputProps()} />
                        {!values.picture ? (
                          <p>아바타로 사용할 이미지 선택</p>
                        ) : (
                          <FlexBetween>
                            <Typography>{values.picture.name}</Typography>
                            <EditOutlinedIcon />
                          </FlexBetween>
                        )}
                      </Box>
                    )}
                  </Dropzone>
                </Box>
              </>
            )}

            <TextField
              label="Phone*"
              onBlur={handleBlur}
              onChange={(e) => inputPhoneNumber(setFieldValue, e)}
              value={values.phone}
              placeholder="'-'없이 전화번호 숫자만 입력"
              name="phone"
              error={Boolean(touched.phone) && Boolean(errors.phone)}
              helperText={touched.phone && errors.phone}
            />

            {isRegister && (
              <>
                <Box display="flex" justifyContent={"space-between"} gap="10px">
                  <TextField
                    fullWidth
                    label="6자리 코드*"
                    type="text"
                    onBlur={handleBlur}
                    onChange={handleChange}
                    value={values.code}
                    name="code"
                    error={Boolean(touched.code) && Boolean(errors.code)}
                    helperText={touched.code && errors.code}
                  />
                  <TextField
                    type="text"
                    value={values.passcode}
                    name="passcode"
                    sx={{ display: "none" }}
                  />
                  <Button
                    disabled={
                      values.name !== "" && values.phone !== "" ? false : true
                    }
                    sx={{
                      p: "1rem",
                      width: "100px",
                      backgroundColor: "#0D6EFD",
                      color: "#fff",
                      "&:hover": { backgroundColor: "#70a8fc" },
                    }}
                    onClick={() => {
                      sendSMS(values, setFieldValue);
                    }}
                  >
                    {sentCode ? "재전송" : "코드전송"}
                  </Button>
                </Box>
                <Typography
                  display={"flex"}
                  justifyContent={"start"}
                  alignItems={"center"}
                  sx={{ fontSize: "11px" }}
                >
                  <ReportIcon sx={{ color: "#f88848" }} />
                  코드요청 버튼을 클릭하고 입력한 전화번호로 발송된 코드를
                  입력하세요
                </Typography>
              </>
            )}
            <TextField
              label="Password*"
              type="password"
              onBlur={handleBlur}
              onChange={handleChange}
              value={values.password}
              name="password"
              error={Boolean(touched.password) && Boolean(errors.password)}
              helperText={touched.password && errors.password}
            />
            {isRegister && (
              <TextField
                label="Password 확인*"
                type="password"
                onBlur={handleBlur}
                onChange={handleChange}
                value={values.passwordVerify}
                name="passwordVerify"
                error={
                  Boolean(touched.passwordVerify) &&
                  Boolean(errors.passwordVerify)
                }
                helperText={touched.passwordVerify && errors.passwordVerify}
              />
            )}
          </Box>

          {/* BUTTONS */}
          <Box>
            <Button
              fullWidth
              type="submit"
              sx={{
                m: "2rem 0",
                p: "1rem",
                backgroundColor: "#0D6EFD",
                color: "#fff",
                "&:hover": { backgroundColor: "#70a8fc" },
              }}
            >
              {isLogin ? "로그인" : "회원가입"}
            </Button>
            <Typography
              display="flex"
              fontSize="12px"
              onClick={() => {
                setPageType(isLogin ? "register" : "login");
                resetForm();
              }}
              sx={{
                color: "#0D6EFD",
                "&:hover": {
                  cursor: "pointer",
                  color: "#7431F9",
                },
              }}
            >
              <ErrorIcon sx={{ fontSize: "16px" }} />
              &nbsp;&nbsp;&nbsp;
              {isLogin
                ? "아직 계정이 없으신가요? 회원가입부터 하세요."
                : "이미 계정이 있으신가요? 로그인하세요."}
            </Typography>
          </Box>
        </form>
      )}
    </Formik>
  );
};

export default LoginPage;
