import { Box, useMediaQuery } from "@mui/material";
import { useSelector, useDispatch } from "react-redux";
import RegistSalesPannel from "scenes/widgets/RegistCompanyPannel";
import RegistCompanyWidget from "scenes/widgets/RegistCompanyWidget";

const RegistCompany = () => {
  const isNonMobileScreens = useMediaQuery("(min-width:1000px)");
  const { _id, picturePath } = useSelector((state) => state.user);
  
  return (
    <Box
      mt="80px"
      width="100%"
      padding="1rem 1.5rem"
      display={isNonMobileScreens ? "flex" : "block"}
      gap="1.5rem"
      justifyContent="center"
    >
      <Box
        flexBasis={isNonMobileScreens ? "25%" : undefined}
        >
        <RegistSalesPannel userId={_id} picturePath={picturePath}/>
      </Box>
      <Box
        flexBasis={isNonMobileScreens ? "75%" : undefined}
        mt={isNonMobileScreens ? undefined : "2rem"}
      >
        <RegistCompanyWidget picturePath={picturePath}/>
      </Box>
    </Box>
  );
};

export default RegistCompany;
