import React from "react";
import ReactDOM from "react-dom/client";
import authReducer from "./state";
import { configureStore } from "@reduxjs/toolkit";
import { Provider } from "react-redux";
import {
  persistStore,
  persistReducer,
  FLUSH,
  REHYDRATE,
  PAUSE,
  PERSIST,
  PURGE,
  REGISTER,
} from "redux-persist";
// 1. 변수명을 storage로 변경하여 브라우저 내장 sessionStorage와의 충돌을 방지합니다.
import storage from "redux-persist/lib/storage/session";
import { PersistGate } from "redux-persist/integration/react";
import App from "./App";

import "./index.css";

// 2. storage 변수를 config에 적용합니다.
const persistConfig = { key: "root", storage: storage, version: 1 };
const persistedReducer = persistReducer(persistConfig, authReducer);

export const store = configureStore({
  reducer: persistedReducer,
  middleware: (getDefaultMiddleware) =>
    getDefaultMiddleware({
      serializableCheck: {
        ignoredActions: [FLUSH, REHYDRATE, PAUSE, PERSIST, PURGE, REGISTER],
      },
    }),
});

// 3. 여기서 한 번만 생성한 persistor 변수를 아래에서 그대로 사용해야 합니다.
export const persistor = persistStore(store);

const root = ReactDOM.createRoot(document.getElementById("root"));
root.render(
  <Provider store={store}>
    {/* 4. 중복 생성 함수인 persistStore(store) 대신, 위에서 export한 persistor 변수를 주입합니다. */}
    <PersistGate loading={null} persistor={persistor}>
      <App />
    </PersistGate>
  </Provider>,
);
