import { Box, useMediaQuery, Typography } from "@mui/material";
import { useState } from "react";
import { useDispatch, useSelector } from "react-redux";
import EditIcon from "@mui/icons-material/Edit";
import {
  setEditData,
  deletePost,
  setTotalSearchCompanies,
} from "state";

import ClearIcon from "@mui/icons-material/Clear";

const PostWidget = ({ post }) => {

  const token = useSelector((state) => state.token);
  const brief = useSelector((state) => state.brief);
  const totalSearchCompanies = useSelector(
    (state) => state.totalSearchCompanies,
  );
  const mainUser = useSelector((state) => state.mainUser)

  const [open, setOpen] = useState(false);

  const dispatch = useDispatch();
  const isMobile = useMediaQuery("(max-width:600px)");

  const editCompany = (company) => {
    dispatch(setEditData(company));
    setOpen(true);
  };

  const deleteCompany = async (company, e) => {
    if (company.sales.length > 0) {
      alert(
        "영업정보가 있는 업체 정보는 삭제할 수 없습니다.\n먼저 영업정보를 모두 삭제하세요.",
      );
      return;
    }

    if (window.confirm("선택한 업체정보를 정말 삭제하시겠습니까?")) {
      const response = await fetch(
        "http://3.37.116.103:3500/data/deleteCompany",
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({
            companyId: post._id,
          }),
        },
      );

      if (!response.ok) {
        const error = await response.json();
        alert(error);
        return;
      }
      
      const data = await response.json();

      dispatch(deletePost(data));
      dispatch(setTotalSearchCompanies(totalSearchCompanies - 1));
    }

  };

  return (
    <Box mt="1rem">
      <Box display="grid" gridTemplateColumns="repeat(4, minmax(0, 1fr))">
        <Box
          gridColumn={isMobile ? "span 4" : "span 1"}
          display="grid"
          gridTemplateColumns="repeat(6, minmax(0, 1fr))"
        >
          <Box
            gridColumn={"span 2"}
            p="4px"
            sx={{
              backgroundColor: "#eee",
            }}
            border="1px solid #ddd"
            textAlign={"center"}
          >
            <Typography>회사명</Typography>
          </Box>
          <Box gridColumn="span 4" p="4px" border="1px solid #ddd">
            <Typography>{post.companyName}</Typography>
          </Box>
        </Box>
        <Box
          gridColumn={isMobile ? "span 4" : "span 1"}
          display="grid"
          gridTemplateColumns="repeat(6, minmax(0, 1fr))"
        >
          <Box
            gridColumn="span 2"
            p="4px"
            sx={{
              backgroundColor: "#eee",
            }}
            border="1px solid #ddd"
            textAlign={"center"}
          >
            <Typography>등록번호</Typography>
          </Box>
          <Box gridColumn="span 4" p="4px" border="1px solid #ddd">
            <Typography>{post.registNo}</Typography>
          </Box>
        </Box>
        <Box
          gridColumn={isMobile ? "span 4" : "span 1"}
          display="grid"
          gridTemplateColumns="repeat(6, minmax(0, 1fr))"
        >
          <Box
            gridColumn="span 2"
            p="4px"
            sx={{
              backgroundColor: "#eee",
            }}
            border="1px solid #ddd"
            textAlign={"center"}
          >
            <Typography>대표</Typography>
          </Box>
          <Box gridColumn="span 4" p="4px" border="1px solid #ddd">
            <Typography>{post.ceo}</Typography>
          </Box>
        </Box>
        <Box
          gridColumn={isMobile ? "span 4" : "span 1"}
          display="grid"
          gridTemplateColumns="repeat(6, minmax(0, 1fr))"
        >
          <Box
            gridColumn="span 2"
            p="4px"
            sx={{
              backgroundColor: "#eee",
            }}
            border="1px solid #ddd"
            textAlign={"center"}
          >
            <Typography>나이</Typography>
          </Box>
          <Box gridColumn="span 4" p="4px" border="1px solid #ddd">
            <Typography>{post.age}</Typography>
          </Box>
        </Box>
      </Box>
      {brief === "상세" ? (
        <>
          <Box display="grid" gridTemplateColumns="repeat(4, minmax(0, 1fr))">
            <Box
              gridColumn={isMobile ? "span 4" : "span 1"}
              display="grid"
              gridTemplateColumns="repeat(6, minmax(0, 1fr))"
            >
              <Box
                gridColumn="span 2"
                p="4px"
                sx={{
                  backgroundColor: "#eee",
                }}
                border="1px solid #ddd"
                textAlign={"center"}
              >
                <Typography>형태</Typography>
              </Box>
              <Box gridColumn="span 4" p="4px" border="1px solid #ddd">
                <Typography>{post.companyType}</Typography>
              </Box>
            </Box>
            <Box
              gridColumn={isMobile ? "span 4" : "span 1"}
              display="grid"
              gridTemplateColumns="repeat(6, minmax(0, 1fr))"
            >
              <Box
                gridColumn="span 2"
                p="4px"
                sx={{
                  backgroundColor: "#eee",
                }}
                border="1px solid #ddd"
                textAlign={"center"}
              >
                <Typography>직원수</Typography>
              </Box>
              <Box
                gridColumn="span 4"
                p="4px 10px"
                border="1px solid #ddd"
                textAlign={"right"}
              >
                <Typography>
                  {post.employees
                    ? Number(post.employees).toLocaleString()
                    : ""}
                </Typography>
              </Box>
            </Box>
            <Box
              gridColumn={isMobile ? "span 4" : "span 1"}
              display="grid"
              gridTemplateColumns="repeat(6, minmax(0, 1fr))"
            >
              <Box
                gridColumn="span 2"
                p="4px"
                sx={{
                  backgroundColor: "#eee",
                }}
                border="1px solid #ddd"
                textAlign={"center"}
              >
                <Typography>매출액</Typography>
              </Box>
              <Box
                gridColumn="span 4"
                p="4px 10px"
                border="1px solid #ddd"
                textAlign={"right"}
              >
                <Typography>
                  {post.grossRevenue
                    ? Number(post.grossRevenue).toLocaleString()
                    : ""}
                </Typography>
              </Box>
            </Box>
            <Box
              gridColumn={isMobile ? "span 4" : "span 1"}
              display="grid"
              gridTemplateColumns="repeat(6, minmax(0, 1fr))"
            >
              <Box
                gridColumn="span 2"
                p="4px"
                sx={{
                  backgroundColor: "#eee",
                }}
                border="1px solid #ddd"
                textAlign={"center"}
              >
                <Typography>순이익</Typography>
              </Box>
              <Box
                gridColumn="span 4"
                p="4px 10px"
                border="1px solid #ddd"
                textAlign={"right"}
              >
                <Typography>
                  {post.netProfit
                    ? Number(post.netProfit).toLocaleString()
                    : ""}
                </Typography>
              </Box>
            </Box>
          </Box>
          <Box
            gridColumn="span 3"
            display="grid"
            gridTemplateColumns="repeat(4, minmax(0, 1fr))"
          >
            <Box
              gridColumn={isMobile ? "span 4" : "span 1"}
              display="grid"
              gridTemplateColumns="repeat(6, minmax(0, 1fr))"
            >
              <Box
                gridColumn="span 2"
                p="4px"
                sx={{
                  backgroundColor: "#eee",
                }}
                border="1px solid #ddd"
                textAlign={"center"}
              >
                <Typography>가지급금</Typography>
              </Box>
              <Box
                gridColumn="span 4"
                p="4px 10px"
                border="1px solid #ddd"
                textAlign={"right"}
              >
                <Typography>
                  {post.suspenseAccount
                    ? Number(post.suspenseAccount).toLocaleString()
                    : ""}
                </Typography>
              </Box>
            </Box>
            <Box
              gridColumn={isMobile ? "span 4" : "span 1"}
              display="grid"
              gridTemplateColumns="repeat(6, minmax(0, 1fr))"
            >
              <Box
                gridColumn="span 2"
                p="4px"
                sx={{
                  backgroundColor: "#eee",
                }}
                border="1px solid #ddd"
                textAlign={"center"}
              >
                <Typography>잉여금</Typography>
              </Box>
              <Box
                gridColumn="span 4"
                p="4px 10px"
                border="1px solid #ddd"
                textAlign={"right"}
              >
                <Typography>
                  {post.retainedEarnings
                    ? Number(post.retainedEarnings).toLocaleString()
                    : ""}
                </Typography>
              </Box>
            </Box>
            <Box
              gridColumn={isMobile ? "span 4" : "span 1"}
              display="grid"
              gridTemplateColumns="repeat(6, minmax(0, 1fr))"
            >
              <Box
                gridColumn="span 2"
                p="4px"
                sx={{
                  backgroundColor: "#eee",
                }}
                border="1px solid #ddd"
                textAlign={"center"}
              >
                <Typography>단체보험</Typography>
              </Box>
              <Box
                gridColumn="span 4"
                p="4px"
                border="1px solid #ddd"
                textAlign={"center"}
              >
                <Typography>{post.groupInsu}</Typography>
              </Box>
            </Box>
            <Box
              gridColumn={isMobile ? "span 4" : "span 1"}
              display="grid"
              gridTemplateColumns="repeat(6, minmax(0, 1fr))"
            >
              <Box
                gridColumn="span 2"
                p="4px"
                sx={{
                  backgroundColor: "#eee",
                }}
                border="1px solid #ddd"
                textAlign={"center"}
              >
                <Typography>법인명의</Typography>
              </Box>
              <Box
                gridColumn="span 4"
                p="4px"
                border="1px solid #ddd"
                textAlign={"center"}
              >
                <Typography>{post.companyInsu}</Typography>
              </Box>
            </Box>
          </Box>
        </>
      ) : null}
      <Box display="grid" gridTemplateColumns="repeat(2, minmax(0, 1fr))">
        <Box
          gridColumn={isMobile ? "span 2" : "span 1"}
          display="grid"
          gridTemplateColumns="repeat(12, minmax(0, 1fr))"
          border="1px solid #ddd"
        >
          <Box
            gridColumn={isMobile ? "span 12" : "span 2"}
            p="4px"
            sx={{
              backgroundColor: "#eee",
            }}
            border="1px solid #ddd"
            textAlign={"center"}
          >
            <Typography>업종</Typography>
          </Box>
          <Box gridColumn={isMobile ? "span 12" : "span 10"} p="4px">
            <Typography>{post.industry}</Typography>
          </Box>
        </Box>
        <Box
          gridColumn={isMobile ? "span 2" : "span 1"}
          display="grid"
          gridTemplateColumns="repeat(12, minmax(0, 1fr))"
          border="1px solid #ddd"
        >
          <Box
            gridColumn={isMobile ? "span 12" : "span 2"}
            p="4px"
            sx={{
              backgroundColor: "#eee",
            }}
            border="1px solid #ddd"
            textAlign={"center"}
          >
            <Typography>주소</Typography>
          </Box>
          <Box gridColumn={isMobile ? "span 12" : "span 10"} p="4px">
            <Typography>
              {post.address}
              {post.phone ? `[Tel:${post.phone}]` : ""}
            </Typography>
          </Box>
        </Box>
      </Box>
      <Box
        gridColumn="span 4"
        display="grid"
        gridTemplateColumns="repeat(4, minmax(0, 1fr))"
      >
        <Box
          gridColumn={isMobile ? "span 4" : "span 1"}
          display="grid"
          gridTemplateColumns="repeat(6, minmax(0, 1fr))"
        >
          <Box
            gridColumn="span 2"
            p="4px"
            sx={{
              backgroundColor: "#eee",
            }}
            border="1px solid #ddd"
            textAlign={"center"}
          >
            <Typography>영업유형</Typography>
          </Box>
          <Box gridColumn="span 4" p="4px" border="1px solid #ddd">
            <Typography>{post.salesType}</Typography>
          </Box>
        </Box>
        <Box
          gridColumn={isMobile ? "span 4" : "span 1"}
          display="grid"
          gridTemplateColumns="repeat(6, minmax(0, 1fr))"
        >
          <Box
            gridColumn="span 2"
            p="4px"
            sx={{
              backgroundColor: "#eee",
            }}
            border="1px solid #ddd"
            textAlign={"center"}
          >
            <Typography>상태</Typography>
          </Box>
          <Box gridColumn="span 4" p="4px" border="1px solid #ddd">
            <Typography>{post.status}</Typography>
          </Box>
        </Box>
        <Box
          gridColumn={isMobile ? "span 4" : "span 1"}
          display="grid"
          gridTemplateColumns="repeat(6, minmax(0, 1fr))"
        >
          <Box
            gridColumn="span 2"
            p="4px"
            sx={{
              backgroundColor: "#eee",
            }}
            border="1px solid #ddd"
            textAlign={"center"}
          >
            <Typography>공동영업</Typography>
          </Box>
          <Box gridColumn="span 4" p="4px" border="1px solid #ddd">
            <Typography>{post.companion}</Typography>
          </Box>
        </Box>
        <Box
          gridColumn={isMobile ? "span 4" : "span 1"}
          display="grid"
          gridTemplateColumns="repeat(6, minmax(0, 1fr))"
        >
          <Box
            gridColumn="span 2"
            p="4px"
            sx={{
              backgroundColor: "#eee",
            }}
            border="1px solid #ddd"
            textAlign={"center"}
          >
            <Typography>그룹</Typography>
          </Box>
          <Box gridColumn="span 4" p="4px" border="1px solid #ddd">
            <Typography>{post.group}</Typography>
          </Box>
        </Box>
        {mainUser ? null :
          <Box
            gridColumn="span 4"
            display="grid"
            gridTemplateColumns="repeat(4, minmax(0, 1fr))"
          >
            <Box
              gridColumn="span 4"
              display="flex"
              justifyContent={"end"}
              gap="10px"
              p="2px"
            >
              <Box
                display="flex"
                justifyContent={"center"}
                alignItems={"center"}
                sx={{ width: "27px", height: "27px", cursor: "pointer" }}
                border="1px solid #5299e0"
                borderRadius={"50%"}
                backgroundColor="#dbebfb"
                p="2px"
                onClick={() => editCompany(post)}
              >
                <EditIcon></EditIcon>
              </Box>
              <Box
                display="flex"
                justifyContent={"center"}
                alignItems={"center"}
                sx={{ width: "27px", height: "27px", cursor: "pointer" }}
                border="1px solid #5299e0"
                borderRadius={"50%"}
                p="2px"
                backgroundColor="#dbebfb"
                onClick={(e) => deleteCompany(post, e)}
              >
                <ClearIcon></ClearIcon>
              </Box>
            </Box>
          </Box>
        }
      </Box>
    </Box>
  );
};

export default PostWidget;
