import {
  Box,
  Typography,
  Divider,
  FormControlLabel,
  useMediaQuery
} from "@mui/material";
import WidgetWrapper from "components/WidgetWrapper";
import FormGroup from "@mui/material/FormGroup";
import Checkbox from "@mui/material/Checkbox";
import FormControl from "@mui/material/FormControl";
import { useSelector } from "react-redux";
import { useState, useEffect} from "react";

const ManagerWidget = () => {
  const token = useSelector((state) => state.token);
  const isMobile = useMediaQuery("(max-width:1200px)");

  const [allUsers, setAllUsers] = useState([]);

  const updateApproval = async (user) => {
      const response = await fetch(
        `http://3.37.116.103:3500/data/updateApproval`,
        {
          method: "POST",
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json",
          },
          body: JSON.stringify({user}),
        },
      );

      if (!response.ok) {
        const error = await response.json();
        alert(error);
        return;
      }
  };
  const updateSuspended = async (user) => {

      const response = await fetch(
        `http://3.37.116.103:3500/data/updateSuspended`,
        {
          method: "POST",
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json",
          },
          body: JSON.stringify({user}),
        },
      );

      if (!response.ok) {
        const error = await response.json();
        alert(error);
        return;
      }
  };

  useEffect(() => {
    const header = {
      name: "성명",
      phone: "전화",
      createdAt: "생성일",
      lastLogined: "최종로그인",
      lastPaymentDate: "최종결재일",
      totalLogin: "총로그인",
      totalCompany: "총업체",
      totalSales: "총영업",
      totalDocument: "총문서",
      approvedDate: "승인일",
      suspendedDate: "중지일"
    }
    const getAllUsers = async () => {

      const response = await fetch(
        `http://3.37.116.103:3500/data/getAllUsers`,
        {
          method: "POST",
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json",
          },
          body: JSON.stringify({}),
        },
      );

      if (!response.ok) {
        const error = await response.json();
        alert(error);
        return;
      }
      const data = await response.json();
      data.unshift(header)
      setAllUsers(data)
    };
    getAllUsers()
  }, [token])
  
  return (
    <WidgetWrapper>
      <Typography mb="20px" sx={{ fontSize: "18px", fontWeight: 600 }}>
        관리자
      </Typography>

      <Typography
        m="20px 20px"
        sx={{ fontSize: "16px", color: "#999", fontWeight: 600 }}
      >
        사용자 관리
      </Typography>

      {allUsers.map((user, index) => {
        if (isMobile && index === 0) return null
        else 
        return <>
        <Box
          p={isMobile ? "0rem 1rem" : "0.5rem 1rem"}
          display="grid"
            gridTemplateColumns="repeat(13, 1fr)"
            justifyContent={"center"}
            alignItems={"center"}
            gap={isMobile ? "0px" : "15px"}
            textAlign={isMobile ? "start" : "center"}
        >
          <Typography
              gridColumn={isMobile ? "span 13" : "span 1"}
            sx={{ fontSize: "14px", color: "#999", fontWeight: 600 }}
          >
            {user.name}
            </Typography>
            <Box
              gridColumn={isMobile ? "span 13" : "span 2"}
            >
            <Typography
              gridColumn={isMobile ? "span 13" : "span 1"}
              sx={{ fontSize: "14px", color: "#999", fontWeight: 600 }}
            >
              {user.phone}
            </Typography>
          </Box>
            <Typography
              gridColumn={isMobile ? "span 13" : "span 1"}
            sx={{ fontSize: "14px", color: "#999", fontWeight: 600 }}
          >
            {user.createdAt.slice(0,10)}
          </Typography>
            <Typography
              gridColumn={isMobile ? "span 13" : "span 1"}
            sx={{ fontSize: "14px", color: "#999", fontWeight: 600 }}
          >
            {user.lastLogined}
          </Typography>
            <Typography
              gridColumn={isMobile ? "span 13" : "span 1"}
            sx={{ fontSize: "14px", color: "#999", fontWeight: 600 }}
          >
            {user.lastPaymentDate}
            </Typography>
            <Box
              gridColumn={isMobile ? "span 13" : "span 3"}
              display="grid"
              gridTemplateColumns={"repeat(4, 1fr)"}
            >
              <Typography
                gridColumn={isMobile ? "span 4" : "span 1"}
              sx={{ fontSize: "14px", color: "#999", fontWeight: 600 }}
            >
              {user.totalLogin}
            </Typography>
              <Typography
                gridColumn={isMobile ? "span 4" : "span 1"}
              sx={{ fontSize: "14px", color: "#999", fontWeight: 600 }}
            >
              {user.totalCompany}
            </Typography>
              <Typography
                gridColumn={isMobile ? "span 4" : "span 1"}
              sx={{ fontSize: "14px", color: "#999", fontWeight: 600 }}
            >
              {user.totalSales}
            </Typography>
              <Typography
                gridColumn={isMobile ? "span 4" : "span 1"}
              sx={{ fontSize: "14px", color: "#999", fontWeight: 600 }}
            >
              {user.totalDocument}
            </Typography>
          </Box>
            <Typography
              gridColumn={isMobile ? "span 13" : "span 1"}
            sx={{ fontSize: "14px", color: "#999", fontWeight: 600 }}
          >
            {user.approvedDate}
          </Typography>
            <Typography
              gridColumn={isMobile ? "span 13" : "span 1"}
            sx={{ fontSize: "14px", color: "#999", fontWeight: 600 }}
          >
            {user.suspendedDate}
            </Typography>
            <Box
            gridColumn={isMobile ? "span 13" : "span 2"}
            >
              {index === 0 ? null :
          <FormControl
            width="100%"
            component="fieldset"
              variant="standard"
              >
            <FormGroup row>
                <FormControlLabel
                  control={
                    <Checkbox
                      checked={user.approval}
                      onChange={(e) => {
                        const updated = allUsers.map((item) => {
                          if (item._id === user._id) {
                            const val = { ...item, approval: e.target.checked }
                            updateApproval(val)
                            return val
                          } else {
                            return item
                          }
                        })
                        setAllUsers(updated)
                      }}
                      name={"approval"}
                    />
                  }
                  label={"승인"}
                />
                <FormControlLabel
                  control={
                    <Checkbox
                      checked={user.suspended}
                      onChange={(e) => {
                          const updated = allUsers.map((item) => {
                          if (item._id === user._id) {
                            const val = { ...item, suspended: e.target.checked }
                            updateSuspended(val)
                            return val
                          } else {
                            return item
                          }
                        })
                        setAllUsers(updated)
                      }}
                      name={"suspended"}
                    />
                  }
                  label={"중지"}
                />
            </FormGroup>
          </FormControl>
            }
            </Box>
        </Box>
          <Divider sx={{
            margin : isMobile ? "20px 0px" : "0"
          }} />
        </>
      }
      )}
    </WidgetWrapper>
  );
};

export default ManagerWidget;
