import { Box, Tooltip, Typography, useMediaQuery } from "@mui/material";
import WidgetWrapper from "components/WidgetWrapper";
import { useSelector, useDispatch } from "react-redux";
import SalesPostsWidget from "scenes/widgets/SalesPostsWidget";
import SearchSalesPannel from "scenes/widgets/SearchSalesPannel";
import DeleteSweepIcon from "@mui/icons-material/DeleteSweep";
import DownloadForOfflineIcon from "@mui/icons-material/DownloadForOffline";
import ExcelJS from "exceljs";
import { saveAs } from "file-saver";
import { useEffect, useRef } from "react";
import { setPosts } from "state";

export const createExcelContents = async (workbook, sheetName, data) => {
  const excelData = [...data].reverse();

  const worksheet = workbook.addWorksheet(sheetName);

  if (data.length === 0) {
    return
  }
  
  // 1. 컬럼 헤더 설정
  worksheet.columns = [
    { header: "회사명", key: "companyName", width: 20 },
    { header: "사업자등록번호", key: "registNo", width: 15 },
    { header: "대표", key: "ceo", width: 15 },
    { header: "나이", key: "age", width: 15 },
    { header: "형태", key: "companyType", width: 15 },
    { header: "직원수", key: "employees", width: 15 },
    { header: "매출액", key: "grossRevenue", width: 15 },
    { header: "순이익", key: "netProfit", width: 15 },
    { header: "가지급금", key: "suspenseAccount", width: 15 },
    { header: "잉여금", key: "retainedEarnings", width: 15 },
    { header: "단체", key: "groupInsu", width: 15 },
    { header: "법인", key: "companyInsu", width: 15 },
    { header: "업종", key: "industry", width: 15 },
    { header: "주소", key: "address", width: 15 },
    { header: "연락처", key: "phone", width: 15 },
  ];

  // 2. 데이터 추가

  let rowNumber = 1;

  excelData.forEach((company) => {
    const companyData = {
      companyName: company.companyName,
      registNo: company.registNo,
      ceo: company.ceo,
      age: company.age,
      companyType: company.companyType,
      employees: company.employees,
      grossRevenue: company.grossRevenue,
      netProfit: company.netProfit,
      suspenseAccount: company.suspenseAccount,
      retainedEarnings: company.retainedEarnings,
      groupInsu: company.groupInsu,
      companyInsu: company.companyInsu,
      industry: company.industry,
      address: company.address,
      phone: company.phone,
    };

    worksheet.addRow(companyData);
    rowNumber += 1;
    const startRowNumber = rowNumber;

    const row = worksheet.getRow(rowNumber);
    row.height = 20;
    row.font = { bold: true, color: { argb: "FFFFFF" } };
    row.alignment = { vertical: "middle" };
    row.eachCell((cell, index) => {
      cell.font = {
        name: "맑은 고딕",
        size: 10,
        bold: true,
        color:
          company.status === "종료"
            ? { argb: "FF666666" }
            : (index === 11 || index === 12) && cell.value === "Y"
              ? { argb: "FFFF0000" }
               : { argb: "FF000000" },
      };
      cell.fill = {
        type: "pattern",
        pattern: "solid",
        fgColor:
          company.status === "종료"
            ? { argb: "FFDDDDDD" }
            : { argb: "FFFDE9D9" },
      };
      cell.border = {
        top: { style: "thin" },
        left: { style: "thin" },
        bottom: { style: "thin" },
        right: { style: "thin" },
      };
      cell.alignment = { vertical: "middle" };
    });

    worksheet.getCell(rowNumber, 4).value = company.age ? +company.age : "";
    worksheet.getCell(rowNumber, 4).numFmt = "#,##0";
    worksheet.getCell(rowNumber, 6).value = company.employees
      ? +company.employees
      : "";
    worksheet.getCell(rowNumber, 6).numFmt = "#,##0";
    worksheet.getCell(rowNumber, 7).value = company.grossRevenue
      ? +company.grossRevenue
      : "";
    worksheet.getCell(rowNumber, 7).numFmt = "#,##0";
    worksheet.getCell(rowNumber, 8).value = company.netProfit
      ? +company.netProfit
      : "";
    worksheet.getCell(rowNumber, 8).numFmt = "#,##0";
    worksheet.getCell(rowNumber, 9).value = company.suspenseAccount
      ? +company.suspenseAccount
      : "";
    worksheet.getCell(rowNumber, 9).numFmt = "#,##0";
    worksheet.getCell(rowNumber, 10).value = company.retainedEarnings
      ? +company.retainedEarnings
      : "";
    worksheet.getCell(rowNumber, 10).numFmt = "#,##0";

    worksheet.getCell(rowNumber, 2).alignment = {
      horizontal: "center",
      vertical: "middle",
    };
    worksheet.getCell(rowNumber, 3).alignment = {
      horizontal: "center",
      vertical: "middle",
    };
    worksheet.getCell(rowNumber, 3).alignment = {
      horizontal: "center",
      vertical: "middle",
    };
    worksheet.getCell(rowNumber, 5).alignment = {
      horizontal: "center",
      vertical: "middle",
    };
    worksheet.getCell(rowNumber, 11).alignment = {
      horizontal: "center",
      vertical: "middle",
    };
    worksheet.getCell(rowNumber, 14).alignment = {
      horizontal: "center",
      vertical: "middle",
    };
    worksheet.getCell(rowNumber, 15).alignment = {
      horizontal: "center",
      vertical: "middle",
    };

    company.sales.forEach((sales) => {
      const salesData = {
        companyName: "",
        registNo: sales.date,
        ceo: sales.salesStatus,
        age: sales.contents,
      };

      worksheet.addRow(salesData);
      rowNumber += 1;
      worksheet.mergeCells(rowNumber, 4, rowNumber, 15);

      const row = worksheet.getRow(rowNumber);
      row.height = 20;
      row.alignment = { vertical: "middle" };
      row.eachCell((cell) => {
        cell.font = {
          name: "맑은 고딕",
          size: 10,
          bold: false,
          color: company.status === "종료" ? { argb: "FF666666" } : { argb: "FF000000" },
        };
        cell.fill = {
          type: "pattern",
          pattern: "solid",
          fgColor:
            company.status === "종료"
              ? { argb: "FFDDDDDD" }
              : { argb: "FFFFFFFF" },
        };
        cell.border = {
          top: { style: "thin" },
          left: { style: "thin" },
          bottom: { style: "thin" },
          right: { style: "thin" },
        };
        cell.alignment = { vertical: "middle" };
      });

      worksheet.getCell(rowNumber, 2).alignment = {
        horizontal: "center",
        vertical: "middle",
      };
      worksheet.getCell(rowNumber, 3).alignment = {
        horizontal: "center",
        vertical: "middle",
      };
    });

    const startRow = startRowNumber;
    const startCol = 1;
    const endRow = rowNumber;
    const endCol = 15;

    // 범위 내의 모든 셀을 순회하며 바깥쪽 테두리만 굵게 적용
    for (let r = startRow; r <= endRow; r++) {
      for (let c = startCol; c <= endCol; c++) {
        const cell = worksheet.getCell(r, c);

        // 기존 테두리 설정 가져오기 (없으면 빈 객체)
        let border = cell.border || {};

        // 1. 위쪽 테두리 (범위의 첫 번째 행인 경우)
        if (r === startRow) {
          border.top = { style: "medium", color: { argb: "000000" } };
        }

        // 2. 아래쪽 테두리 (범위의 마지막 행인 경우)
        if (r === endRow) {
          border.bottom = { style: "medium", color: { argb: "000000" } };
        }

        // 3. 왼쪽 테두리 (범위의 첫 번째 열인 경우)
        if (c === startCol) {
          border.left = { style: "medium", color: { argb: "000000" } };
        }

        // 4. 오른쪽 테두리 (범위의 마지막 열인 경우)
        if (c === endCol) {
          border.right = { style: "medium", color: { argb: "000000" } };
        }

        // 셀에 테두리 객체 적용
        cell.border = border;
      }
    }
  });

  // 3. 스타일링: 헤더 스타일 적용
  const headerRow = worksheet.getRow(1);
  headerRow.height = 20;
  headerRow.font = { bold: true, color: { argb: "FFFFFF" } };
  headerRow.eachCell((cell) => {
    cell.font = {
      name: "맑은 고딕",
      size: 10,
      bold: true,
      color: { argb: "FF000000" },
    };
    cell.fill = {
      type: "pattern",
      pattern: "solid",
      fgColor: { argb: "FFC4D79B" },
    };
    cell.alignment = { vertical: "middle", horizontal: "center" };
    cell.border = {
      top: { style: "thin" },
      left: { style: "thin" },
      bottom: { style: "thin" },
      right: { style: "thin" },
    };
  });

  headerRow.alignment = { vertical: "middle", horizontal: "center" };

  const startRow = 1;
  const startCol = 1;
  const endRow = 1;
  const endCol = 15;

  // 범위 내의 모든 셀을 순회하며 바깥쪽 테두리만 굵게 적용
  for (let r = startRow; r <= endRow; r++) {
    for (let c = startCol; c <= endCol; c++) {
      const cell = worksheet.getCell(r, c);

      // 기존 테두리 설정 가져오기 (없으면 빈 객체)
      let border = cell.border || {};

      // 1. 위쪽 테두리 (범위의 첫 번째 행인 경우)
      if (r === startRow) {
        border.top = { style: "medium", color: { argb: "000000" } };
      }

      // 2. 아래쪽 테두리 (범위의 마지막 행인 경우)
      if (r === endRow) {
        border.bottom = { style: "medium", color: { argb: "000000" } };
      }

      // 3. 왼쪽 테두리 (범위의 첫 번째 열인 경우)
      if (c === startCol) {
        border.left = { style: "medium", color: { argb: "000000" } };
      }

      // 4. 오른쪽 테두리 (범위의 마지막 열인 경우)
      if (c === endCol) {
        border.right = { style: "medium", color: { argb: "000000" } };
      }

      // 셀에 테두리 객체 적용
      cell.border = border;
    }
  }
};

const SearchSales = () => {

  const dispatch = useDispatch();
  const isNonMobileScreens = useMediaQuery("(min-width:1000px)");
  const { _id, picturePath } = useSelector((state) => state.user);
  const posts = useSelector((state) => state.posts);
  const totalSearchSales = useSelector((state) => state.totalSearchSales);
  const editData = useSelector((state) => state.editData);

  const inputEl = useRef(null);

  useEffect(() => {
    const myFile = new File(["file content"], "example.txt", {
      type: "text/plain",
    });

    const dataTransfer = new DataTransfer();
    dataTransfer.items.add(myFile);

    if (inputEl.current) inputEl.current.files = dataTransfer.files;
  }, [inputEl.current]);

  const download = async () => {
    const workbook = new ExcelJS.Workbook();

    await createExcelContents(workbook, "Sheet1", posts);

    const buffer = await workbook.xlsx.writeBuffer();
    const blob = new Blob([buffer], {
      type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
    });

    const now = new Date();

    const year = now.getFullYear();
    const month = String(now.getMonth() + 1).padStart(2, "0");
    const day = String(now.getDate()).padStart(2, "0");
    const hours = String(now.getHours()).padStart(2, "0");
    const minutes = String(now.getMinutes()).padStart(2, "0");
    const seconds = String(now.getSeconds()).padStart(2, "0");

    // 원하는 형태로 조합 (예: 20260712_215200)
    const formattedDateTime = `${year}${month}${day}_${hours}${minutes}${seconds}_`;

    saveAs(blob, formattedDateTime + "sales_data.xlsx");
  };

  return (
    <Box
      mt="80px"
      width="100%"
      padding="1rem 1.5rem"
      display={isNonMobileScreens ? "flex" : "block"}
      gap="1.5rem"
      justifyContent="center"
    >
      <Box flexBasis={isNonMobileScreens ? "25%" : undefined}>
        <SearchSalesPannel userId={_id} picturePath={picturePath} />
      </Box>
      <Box
        flexBasis={isNonMobileScreens ? "75%" : undefined}
        mt={isNonMobileScreens ? undefined : "2rem"}
      >
        <WidgetWrapper>
          <Box
            display="flex"
            justifyContent={"space-between"}
            alignItems={"center"}
          >
            <Typography fontWeight={"600"}>
              검색결과: {posts.length > 100 ? 100 : posts.length}건/{totalSearchSales}건
            </Typography>
            <Box display="flex" gap="10px">
              <Tooltip title="엑셀다운로드">
                <DownloadForOfflineIcon
                  sx={{
                    fontSize: "30px",
                    cursor: "pointer",
                    color: "#0073E6",
                  }}
                  onClick={() => download()}
                />
              </Tooltip>
              <Tooltip title="검색결과삭제">
                <DeleteSweepIcon
                  sx={{
                    fontSize: "30px",
                    cursor: "pointer",
                    color: "#0073E6",
                  }}
                  onClick={() => dispatch(setPosts({ posts: [] }))}
                />
              </Tooltip>
            </Box>
          </Box>
          <SalesPostsWidget />
        </WidgetWrapper>
      </Box>
    </Box>
  );
};

export default SearchSales;
