import { useState } from "react";
import { useDispatch, useSelector } from "react-redux";
import {
  Box,
  Button,
  TextField,
  RadioGroup,
  FormControlLabel,
  Radio,
} from "@mui/material";
import Accordion from "@mui/material/Accordion";
import AccordionSummary from "@mui/material/AccordionSummary";
import AccordionDetails from "@mui/material/AccordionDetails";
import Typography from "@mui/material/Typography";
import ExpandMoreIcon from "@mui/icons-material/ExpandMore";
import MenuItem from "@mui/material/MenuItem";
import FormControl from "@mui/material/FormControl";
import * as yup from "yup";
import { setPosts, setEditData, setBrief, setTotalSearchSales } from "state";

import { Formik } from "formik";

const inputSchema = yup.object().shape({
  lapse: yup.string(),
  brief: yup.string(),
  region1: yup.string(),
  region2: yup.string(),
  region3: yup.string(),
  salesType: yup.string(),
  status: yup.string(),
  companion: yup.string(),
  group: yup.string(),
});

const initialValues = {
  lapse: "",
  brief: "요약",
  region1: "",
  region2: "",
  region3: "",
  salesType: "전체",
  status: "전체",
  companion: "전체",
  group: "전체",
};

const Form = () => {
  const dispatch = useDispatch();
  const token = useSelector((state) => state.token);
  const user = useSelector((state) => state.user);

  const [groups, setGroups] = useState([]);

  const search = async (values, onSubmitProps) => {
    dispatch(setEditData(null));
    values.userId = user._id;

    const response = await fetch(
      "http://3.37.116.103:3500/data/searchSalesLapse",
      {
        method: "POST",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify(values),
      },
    );
    const data = await response.json();

    dispatch(setPosts({ posts: data.companies }));
    dispatch(setTotalSearchSales(data.count));
    
    if (data.count === 0) {
      alert("검색조건에 맞는 데이터가 없습니다.")
    }
  };

  const handleFormSubmit = async (values, onSubmitProps) => {
    await search(values, onSubmitProps);
  };

  const handleInputChange = (setFieldValue, e) => {
    let value = e.target.value.replace(/,/g, "");

    value = value.replace(/[^0-9]/g, "");

    setFieldValue("lapse", value);
  };

  return (
    <Formik
      onSubmit={handleFormSubmit}
      initialValues={initialValues}
      validationSchema={inputSchema}
    >
      {({
        values,
        errors,
        touched,
        handleBlur,
        handleChange,
        handleSubmit,
        setFieldValue,
        submitForm,
        resetForm,
      }) => (
        <form onSubmit={handleSubmit}>
          <Box display="grid" gap="20px">
            <Typography
              mb={"15px"}
              sx={{ fontSize: "14px", fontWeight: "500" }}
            >
              ※ '마지막 영업일자'를 기준으로...
            </Typography>
            <Box
              display={"flex"}
              justifyContent={"space-between"}
              alignItems={"center"}
              gap={"5px"}
            >
              <TextField
                fullWidth
                label="경과기간"
                onChange={(e) => handleInputChange(setFieldValue, e)}
                value={values.lapse}
                name="lapse"
                sx={{
                  input: { textAlign: "right" },
                }}
              />
              <Typography sx={{ width: "60px" }}>일 이상</Typography>
            </Box>
            <FormControl>
              <RadioGroup
                row
                name="brief"
                value={values.brief}
                onChange={(e) => {
                  dispatch(setBrief(e.target.value));
                  setFieldValue("brief", e.target.value);
                }}
              >
                <FormControlLabel
                  label="요약정보"
                  value={"요약"}
                  control={
                    <Radio
                      sx={{
                        color: "#79058e",
                        "&.Mui-checked": {
                          color: "#79058e",
                        },
                      }}
                    />
                  }
                />
                <FormControlLabel
                  label="상세정보"
                  value={"상세"}
                  control={
                    <Radio
                      sx={{
                        color: "#79058e",
                        "&.Mui-checked": {
                          color: "#79058e",
                        },
                      }}
                    />
                  }
                />
              </RadioGroup>
            </FormControl>
            <FormControl fullWidth>
              <TextField
                select
                value={values.companion}
                label="공동영업"
                name="companion"
                onChange={(e) => {
                  setFieldValue("companion", e.target.value);
                  if (e.target.value === "전체") {
                    setGroups([]);
                  } else {
                    const companion = user.companion.find(
                      (value) => value.name === e.target.value,
                    );
                    if (e.target.value === "미지정") {
                      setGroups([]);
                    } else {
                      setGroups([...companion.groups]);
                    }
                  }
                }}
              >
                <MenuItem value={"전체"}>전체</MenuItem>
                <MenuItem value={"미지정"}>미지정</MenuItem>
                {user.companion?.map((item) => (
                  <MenuItem value={item.name}>{item.name}</MenuItem>
                ))}
              </TextField>
            </FormControl>
            <FormControl fullWidth>
              <TextField
                disabled={values.companion !== "미지정" ? false : true}
                select
                value={values.group}
                label="그룹"
                name="group"
                onChange={handleChange}
              >
                <MenuItem value={"전체"}>전체</MenuItem>
                {groups.map((item) => (
                  <MenuItem value={item}>{item}</MenuItem>
                ))}
              </TextField>
            </FormControl>
            <FormControl fullWidth>
              <TextField
                select
                value={values.salesType}
                label="영업유형"
                name="salesType"
                onChange={handleChange}
              >
                <MenuItem value={"전체"}>전체</MenuItem>
                <MenuItem value={"개척"}>개척</MenuItem>
                <MenuItem value={"타겟"}>타겟</MenuItem>
                <MenuItem value={"TA"}>TA</MenuItem>
                <MenuItem value={"소개"}>소개</MenuItem>
              </TextField>
            </FormControl>
            <FormControl fullWidth>
              <TextField
                select
                value={values.status}
                label="영업상태"
                name="status"
                error={Boolean(touched.status) && Boolean(errors.status)}
                helperText={touched.status && errors.status}
                onChange={handleChange}
              >
                <MenuItem value={"전체"}>전체</MenuItem>
                <MenuItem value={"등록"}>등록</MenuItem>
                <MenuItem value={"재방"}>재방</MenuItem>
                <MenuItem value={"상"}>상</MenuItem>
                <MenuItem value={"중"}>중</MenuItem>
                <MenuItem value={"하"}>하</MenuItem>
                {values.exceptEnd === "종료포함" ? (
                  <MenuItem value={"종료"}>종료</MenuItem>
                ) : null}
              </TextField>
            </FormControl>
            <Accordion>
              <AccordionSummary
                expandIcon={<ExpandMoreIcon />}
                aria-controls="panel1-content"
                id="panel1-header"
              >
                <Typography component="span">지역</Typography>
              </AccordionSummary>
              <AccordionDetails>
                <Box display="grid" gap="20px">
                  <TextField
                    label="지역1"
                    onBlur={handleBlur}
                    onChange={handleChange}
                    value={values.region1}
                    name="region1"
                  />
                  <TextField
                    label="지역2"
                    onBlur={handleBlur}
                    onChange={handleChange}
                    value={values.region2}
                    name="region2"
                  />
                  <TextField
                    label="지역3"
                    onBlur={handleBlur}
                    onChange={handleChange}
                    value={values.region3}
                    name="region3"
                  />
                </Box>
              </AccordionDetails>
            </Accordion>
          </Box>
          <Box display={"grid"} gridTemplateColumns={"1fr 1fr"} gap={"20px"}>
            <Button
              type="submit"
              sx={{
                m: "2rem 0",
                p: "1rem",
                backgroundColor: "#0073E6",
                color: "#fff",
                "&:hover": { backgroundColor: "#5299e0" },
              }}
            >
              검색
            </Button>
            <Button
              type="submit"
              sx={{
                m: "2rem 0",
                p: "1rem",
                backgroundColor: "#0073E6",
                color: "#fff",
                "&:hover": { backgroundColor: "#5299e0" },
              }}
              onClick={() => resetForm()}
            >
              초기화
            </Button>
          </Box>
        </form>
      )}
    </Formik>
  );
};

export default Form;
