import { useDispatch, useSelector } from "react-redux";
import CompanyPostWidget from "./CompanyPostWidget";
import { setEditData } from "state";

const CompanyPostsWidget = () => {
  const dispatch = useDispatch()
  const posts = useSelector((state) => state.posts);
  dispatch(setEditData(null))

  return (
    <>
      {posts.map((post) => (
        <CompanyPostWidget key={post._id} post={post} />
      ))}
    </>
    )
};

export default CompanyPostsWidget;
