import { useState } from "react";
import {
  Box,
  Typography
} from "@mui/material";
import WidgetWrapper from "components/WidgetWrapper";
import SearchSalesNormal from "./SearchSalesNormal"
import SearchSalesLapse from "./SearchSalesLapse"
import Tabs from '@mui/material/Tabs';
import Tab from '@mui/material/Tab';
import { useDispatch } from "react-redux";

import { setPosts } from "state";

const SearchSalesPannel = () => {

  const dispatch = useDispatch()

  const [searchType, setSearchType] = useState(0);

  const handleChange = (e, newValue) => {
    dispatch(setPosts({posts: []}))
    setSearchType(newValue)
  }

  return (
    <WidgetWrapper>
      <Typography
        color={"#555"}
        mb={"15px"}
        sx={{
          fontWeight: "700",
          fontSize: "18px",
        }}
      >
        영업관리 및 검색
      </Typography>

      <Box sx={{ borderBottom: 1, borderColor: 'divider'}}>
        <Tabs
          value={searchType}
          onChange={handleChange}
          slotProps={{
            indicator: { sx: { height: '4px' } }
          }}>
          <Tab sx={{fontSize: "14px"}} label="일반" />
          <Tab sx={{fontSize: "14px"}} label="경과기간"/>
        </Tabs>
      </Box>
      <Box
        sx={{ mt: "25px" }}
      >
        {
          searchType === 0 ? <SearchSalesNormal/> : <SearchSalesLapse/>
        }
      </Box>
    </WidgetWrapper>
  )

};

export default SearchSalesPannel;
