import { BrowserRouter, Navigate, Routes, Route } from "react-router-dom";
import { useMemo } from "react";
import { useSelector } from "react-redux";
import { CssBaseline, ThemeProvider } from "@mui/material";
import { createTheme } from "@mui/material/styles";
import { themeSettings } from "./theme";

import LoginPage from "scenes/loginPage";
import SearchSales from "scenes/SearchSalesPage";
import RegistCompany from "scenes/RegistCompanyPage";
import SearchCompany from "scenes/SearchCompanyPage";
import MyPage from "scenes/MyPage";
import Reporting from "scenes/Reporting";
import Manager from "scenes/Manager";
import Layout from "scenes/Layout";

function App() {
  const mode = useSelector((state) => state.mode);
  const theme = useMemo(() => createTheme(themeSettings(mode)), [mode]);

  const isAuth = Boolean(useSelector((state) => state.token));

  return (
    <div className="app" height="100vh">
      <BrowserRouter>
        <ThemeProvider theme={theme}>
          <CssBaseline />
          <Routes>
            <Route
              path="/"
              element={
                isAuth ? <Navigate to="/registcompany" /> : <LoginPage />
              }
            />
            <Route element={<Layout />}>
              <Route
                path="/searchsales"
                element={isAuth ? <SearchSales /> : <Navigate to="/" />}
              ></Route>
              <Route
                path="/registcompany"
                element={isAuth ? <RegistCompany /> : <Navigate to="/" />}
              ></Route>
              <Route
                path="/searchcompany"
                element={isAuth ? <SearchCompany /> : <Navigate to="/" />}
              ></Route>
              <Route
                path="/mypage"
                element={isAuth ? <MyPage /> : <Navigate to="/" />}
              ></Route>
              <Route
                path="/reporting"
                element={isAuth ? <Reporting /> : <Navigate to="/" />}
              ></Route>
              <Route
                path="/manager"
                element={isAuth ? <Manager /> : <Navigate to="/" />}
              ></Route>
            </Route>
          </Routes>
        </ThemeProvider>
      </BrowserRouter>
    </div>
  );
}

export default App;
