import { createSlice } from "@reduxjs/toolkit";

const initialState = {
  mode: "light",
  user: null,
  token: null,
  menu: 1,
  posts: [],
  totalSearchCompanies: 0,
  totalSearchSales: 0,
  editData: null,
  brief: "요약",
  exceptEnd: "종료제외",
  mainUser: "",
};

export const authSlice = createSlice({
  name: "auth",
  initialState,
  reducers: {
    setUser: (state, action) => {
      state.user = action.payload;
    },
    setMainUser: (state, action) => {
      state.mainUser = action.payload;
    },
    setTotalSearchCompanies: (state, action) => {
      state.totalSearchCompanies = action.payload;
    },
    setTotalSearchSales: (state, action) => {
      state.totalSearchSales = action.payload;
    },
    setMode: (state) => {
      state.mode = state.mode === "light" ? "dark" : "light";
    },
    setBrief: (state, action) => {
      state.brief = action.payload
    },
    setLogin: (state, action) => {
      state.user = action.payload.user;
      state.token = action.payload.token;
    },
    setLogout: (state) => {
      return {
        ...initialState
      }
    },
    setMenu: (state, action) => {
      state.menu = action.payload;
    },
    setExceptEnd: (state, action) => {
      state.exceptEnd = action.payload;
    },
    setEditData: (state, action) => {
      state.editData = action.payload;
    },
    setPosts: (state, action) => {
      state.posts = action.payload.posts;
    },
    updatePosts: (state, action) => {
      state.posts = state.posts.map((post) => 
        post._id === action.payload._id ? action.payload : post
      )
    },
    deletePost: (state, action) => {
      state.posts = state.posts.filter((post) => 
        post._id !== action.payload._id
      )
    },
  },
});

export const {
  setMode,
  setLogin,
  setLogout,
  setPosts,
  setPost,
  setMenu,
  setEditData,
  updatePosts,
  deletePost,
  setUser,
  setBrief,
  setExceptEnd,
  setTotalSearchCompanies,
  setTotalSearchSales,
  setMainUser
} = authSlice.actions;
export default authSlice.reducer;
