import { Box, useMediaQuery, Typography } from "@mui/material";
import { Fragment } from "react";
import { useDispatch, useSelector } from "react-redux";
import EditIcon from "@mui/icons-material/Edit";
import { setEditData, updatePosts } from "state";
import AddIcon from "@mui/icons-material/Add";
import ClearIcon from "@mui/icons-material/Clear";
import DescriptionOutlinedIcon from "@mui/icons-material/DescriptionOutlined";

const PostWidget = ({
  post,
  setOpen,
  selectedItem,
  setSelectedItem,
  setSelectedPost,
}) => {
  const token = useSelector((state) => state.token);
  const brief = useSelector((state) => state.brief);
  const mainUser = useSelector((state) => state.mainUser);
  const editData = useSelector((state) => state.editData);

  const dispatch = useDispatch();
  const isMobile = useMediaQuery("(max-width:600px)");

  const addSales = (e) => {
    setSelectedPost(post);

    if (post.status === "종료") {
      alert("영업종료된 업체에는 영업정보를 추가할 수 없습니다.");
      return;
    }

    setSelectedItem(null);
    dispatch(setEditData(null));
    setOpen(true);
  };

  const editSales = () => {
    setSelectedPost(post);

    if (!editData) {
      alert("먼저 수정할 영업정보를 선택하세요.");
      return;
    }
    setOpen(true);
  };

  const deleteSales = async (e) => {
    if (post.status === "종료") {
      alert("영업종료된 업체의 영업정보는 삭제할 수 없습니다.");
      return;
    }

    if (!editData) {
      alert("먼저 삭제할 영업정보를 선택하세요.");
      return;
    }

    const goStop = window.confirm(`선택한 영업정보를 정말 삭제하시겠습니까?\n삭제된 정보는 다시 복구할 수 없습니다.`)

    if (goStop) {
      const response = await fetch(
        "http://3.37.116.103:3500/data/deleteSales",
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({
            companyId: post._id,
            salesId: editData._id,
            savedDocName: editData.savedDocName,
          }),
        },
      );

      if (!response.ok) {
        const error = await response.json();
        alert(error);
        return;
      }
      
      const data = await response.json();
      dispatch(updatePosts(data));
    }
  };

  const handleCheckChange = (id, e) => {
    setSelectedItem(selectedItem === id ? null : id);

    if (e.target.checked) {
      const item = post.sales.find((item) => item._id === id);

      dispatch(setEditData(item));
    } else {
      dispatch(setEditData(null));
    }
  };

  const toDataURL = (filename) => {
    return fetch("http://3.37.116.103:3500/files/" + filename)
      .then((response) => {
        return response.blob();
      })
      .then((blob) => {
        return URL.createObjectURL(blob);
      });
  };

  const downloadFile = async (filename) => {
    const a = document.createElement("a");
    a.href = await toDataURL(filename);
    a.download = filename ?? "download";

    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
  };

  return (
    <Box mt="1rem">
      <Box display="grid" gridTemplateColumns="repeat(4, minmax(0, 1fr))">
        <Box
          gridColumn={isMobile ? "span 4" : "span 1"}
          display="grid"
          gridTemplateColumns="repeat(6, minmax(0, 1fr))"
        >
          <Box
            gridColumn={"span 2"}
            p="4px"
            sx={{
              backgroundColor: "#eee",
            }}
            border="1px solid #ddd"
            textAlign={"center"}
          >
            <Typography>회사명</Typography>
          </Box>
          <Box gridColumn="span 4" p="4px" border="1px solid #ddd">
            <Typography color={post.status === "종료" ? "#aaa" : null}>
              {post.companyName}
            </Typography>
          </Box>
        </Box>
        <Box
          gridColumn={isMobile ? "span 4" : "span 1"}
          display="grid"
          gridTemplateColumns="repeat(6, minmax(0, 1fr))"
        >
          <Box
            gridColumn="span 2"
            p="4px"
            sx={{
              backgroundColor: "#eee",
            }}
            border="1px solid #ddd"
            textAlign={"center"}
          >
            <Typography>등록번호</Typography>
          </Box>
          <Box gridColumn="span 4" p="4px" border="1px solid #ddd">
            <Typography color={post.status === "종료" ? "#aaa" : null}>
              {post.registNo}
            </Typography>
          </Box>
        </Box>
        <Box
          gridColumn={isMobile ? "span 4" : "span 1"}
          display="grid"
          gridTemplateColumns="repeat(6, minmax(0, 1fr))"
        >
          <Box
            gridColumn="span 2"
            p="4px"
            sx={{
              backgroundColor: "#eee",
            }}
            border="1px solid #ddd"
            textAlign={"center"}
          >
            <Typography>대표</Typography>
          </Box>
          <Box gridColumn="span 4" p="4px" border="1px solid #ddd">
            <Typography color={post.status === "종료" ? "#aaa" : null}>
              {post.ceo}
            </Typography>
          </Box>
        </Box>
        <Box
          gridColumn={isMobile ? "span 4" : "span 1"}
          display="grid"
          gridTemplateColumns="repeat(6, minmax(0, 1fr))"
        >
          <Box
            gridColumn="span 2"
            p="4px"
            sx={{
              backgroundColor: "#eee",
            }}
            border="1px solid #ddd"
            textAlign={"center"}
          >
            <Typography>나이</Typography>
          </Box>
          <Box
            gridColumn="span 4"
            p="4px"
            border="1px solid #ddd"
            textAlign={"right"}
          >
            <Typography color={post.status === "종료" ? "#aaa" : null}>
              {post.age}
            </Typography>
          </Box>
        </Box>
      </Box>
      {brief === "상세" ? (
        <>
          <Box display="grid" gridTemplateColumns="repeat(4, minmax(0, 1fr))">
            <Box
              gridColumn={isMobile ? "span 4" : "span 1"}
              display="grid"
              gridTemplateColumns="repeat(6, minmax(0, 1fr))"
            >
              <Box
                gridColumn="span 2"
                p="4px"
                sx={{
                  backgroundColor: "#eee",
                }}
                border="1px solid #ddd"
                textAlign={"center"}
              >
                <Typography>형태</Typography>
              </Box>
              <Box gridColumn="span 4" p="4px" border="1px solid #ddd">
                <Typography color={post.status === "종료" ? "#aaa" : null}>
                  {post.companyType}
                </Typography>
              </Box>
            </Box>
            <Box
              gridColumn={isMobile ? "span 4" : "span 1"}
              display="grid"
              gridTemplateColumns="repeat(6, minmax(0, 1fr))"
            >
              <Box
                gridColumn="span 2"
                p="4px"
                sx={{
                  backgroundColor: "#eee",
                }}
                border="1px solid #ddd"
                textAlign={"center"}
              >
                <Typography>직원수</Typography>
              </Box>
              <Box
                gridColumn="span 4"
                p="4px 10px"
                border="1px solid #ddd"
                textAlign={"right"}
              >
                <Typography color={post.status === "종료" ? "#aaa" : null}>
                  {post.employees
                    ? Number(post.employees).toLocaleString()
                    : ""}
                </Typography>
              </Box>
            </Box>
            <Box
              gridColumn={isMobile ? "span 4" : "span 1"}
              display="grid"
              gridTemplateColumns="repeat(6, minmax(0, 1fr))"
            >
              <Box
                gridColumn="span 2"
                p="4px"
                sx={{
                  backgroundColor: "#eee",
                }}
                border="1px solid #ddd"
                textAlign={"center"}
              >
                <Typography>매출액</Typography>
              </Box>
              <Box
                gridColumn="span 4"
                p="4px 10px"
                border="1px solid #ddd"
                textAlign={"right"}
              >
                <Typography color={post.status === "종료" ? "#aaa" : null}>
                  {post.grossRevenue
                    ? Number(post.grossRevenue).toLocaleString()
                    : ""}
                </Typography>
              </Box>
            </Box>
            <Box
              gridColumn={isMobile ? "span 4" : "span 1"}
              display="grid"
              gridTemplateColumns="repeat(6, minmax(0, 1fr))"
            >
              <Box
                gridColumn="span 2"
                p="4px"
                sx={{
                  backgroundColor: "#eee",
                }}
                border="1px solid #ddd"
                textAlign={"center"}
              >
                <Typography>순이익</Typography>
              </Box>
              <Box
                gridColumn="span 4"
                p="4px 10px"
                border="1px solid #ddd"
                textAlign={"right"}
              >
                <Typography color={post.status === "종료" ? "#aaa" : null}>
                  {post.netProfit
                    ? Number(post.netProfit).toLocaleString()
                    : ""}
                </Typography>
              </Box>
            </Box>
          </Box>
          <Box
            gridColumn="span 3"
            display="grid"
            gridTemplateColumns="repeat(4, minmax(0, 1fr))"
          >
            <Box
              gridColumn={isMobile ? "span 4" : "span 1"}
              display="grid"
              gridTemplateColumns="repeat(6, minmax(0, 1fr))"
            >
              <Box
                gridColumn="span 2"
                p="4px"
                sx={{
                  backgroundColor: "#eee",
                }}
                border="1px solid #ddd"
                textAlign={"center"}
              >
                <Typography>가지급금</Typography>
              </Box>
              <Box
                gridColumn="span 4"
                p="4px 10px"
                border="1px solid #ddd"
                textAlign={"right"}
              >
                <Typography color={post.status === "종료" ? "#aaa" : null}>
                  {post.suspenseAccount
                    ? Number(post.suspenseAccount).toLocaleString()
                    : ""}
                </Typography>
              </Box>
            </Box>
            <Box
              gridColumn={isMobile ? "span 4" : "span 1"}
              display="grid"
              gridTemplateColumns="repeat(6, minmax(0, 1fr))"
            >
              <Box
                gridColumn="span 2"
                p="4px"
                sx={{
                  backgroundColor: "#eee",
                }}
                border="1px solid #ddd"
                textAlign={"center"}
              >
                <Typography>잉여금</Typography>
              </Box>
              <Box
                gridColumn="span 4"
                p="4px 10px"
                border="1px solid #ddd"
                textAlign={"right"}
              >
                <Typography color={post.status === "종료" ? "#aaa" : null}>
                  {post.retainedEarnings
                    ? Number(post.retainedEarnings).toLocaleString()
                    : ""}
                </Typography>
              </Box>
            </Box>
            <Box
              gridColumn={isMobile ? "span 4" : "span 1"}
              display="grid"
              gridTemplateColumns="repeat(6, minmax(0, 1fr))"
            >
              <Box
                gridColumn="span 2"
                p="4px"
                sx={{
                  backgroundColor: "#eee",
                }}
                border="1px solid #ddd"
                textAlign={"center"}
              >
                <Typography>단체보험</Typography>
              </Box>
              <Box
                gridColumn="span 4"
                p="4px"
                border="1px solid #ddd"
                textAlign={"center"}
              >
                <Typography color={post.status === "종료" ? "#aaa" : null}>
                  {post.groupInsu}
                </Typography>
              </Box>
            </Box>
            <Box
              gridColumn={isMobile ? "span 4" : "span 1"}
              display="grid"
              gridTemplateColumns="repeat(6, minmax(0, 1fr))"
            >
              <Box
                gridColumn="span 2"
                p="4px"
                sx={{
                  backgroundColor: "#eee",
                }}
                border="1px solid #ddd"
                textAlign={"center"}
              >
                <Typography>법인명의</Typography>
              </Box>
              <Box
                gridColumn="span 4"
                p="4px"
                border="1px solid #ddd"
                textAlign={"center"}
              >
                <Typography color={post.status === "종료" ? "#aaa" : null}>
                  {post.companyInsu}
                </Typography>
              </Box>
            </Box>
          </Box>
        </>
      ) : null}
      <Box display="grid" gridTemplateColumns="repeat(2, minmax(0, 1fr))">
        <Box
          gridColumn={isMobile ? "span 2" : "span 1"}
          display="grid"
          gridTemplateColumns="repeat(12, minmax(0, 1fr))"
          border="1px solid #ddd"
        >
          <Box
            gridColumn={isMobile ? "span 12" : "span 2"}
            p="4px"
            sx={{
              backgroundColor: "#eee",
            }}
            border="1px solid #ddd"
            textAlign={"center"}
          >
            <Typography>업종</Typography>
          </Box>
          <Box gridColumn={isMobile ? "span 12" : "span 10"} p="4px">
            <Typography color={post.status === "종료" ? "#aaa" : null}>
              {post.industry}
            </Typography>
          </Box>
        </Box>
        <Box
          gridColumn={isMobile ? "span 2" : "span 1"}
          display="grid"
          gridTemplateColumns="repeat(12, minmax(0, 1fr))"
          border="1px solid #ddd"
        >
          <Box
            gridColumn={isMobile ? "span 12" : "span 2"}
            p="4px"
            sx={{
              backgroundColor: "#eee",
            }}
            border="1px solid #ddd"
            textAlign={"center"}
          >
            <Typography>주소</Typography>
          </Box>
          <Box gridColumn={isMobile ? "span 12" : "span 10"} p="4px">
            <Typography color={post.status === "종료" ? "#aaa" : null}>
              {post.address}
              {post.phone !== "" ? " [Tel: " + post.phone + "]" : null}
            </Typography>
          </Box>
        </Box>
      </Box>
      {post.sales.map((item, index) => (
        <Fragment key={item._id}>
          <Box display="grid">
            <Box
              display="grid"
              gridTemplateColumns="repeat(24, minmax(0, 1fr))"
            >
              <Box
                gridColumn={isMobile ? "span 24" : "span 5"}
                display="grid"
                gridTemplateColumns="repeat(5, minmax(0, 1fr))"
              >
                <Box
                  gridColumn="span 3"
                  p="4px"
                  border="1px solid #ddd"
                  textAlign={"center"}
                  display="flex"
                  justifyContent={"center"}
                  alignItems={"center"}
                  gap="10px"
                >
                  <input
                    type="checkbox"
                    checked={selectedItem === item._id}
                    onChange={(e) => handleCheckChange(item._id, e)}
                  ></input>
                  <Typography color={post.status === "종료" ? "#aaa" : null}>
                    {item.date}
                  </Typography>
                </Box>
                <Box
                  gridColumn="span 2"
                  p="4px"
                  border="1px solid #ddd"
                  textAlign={"center"}
                >
                  <Typography color={post.status === "종료" ? "#aaa" : null}>
                    {item.salesStatus}
                  </Typography>
                </Box>
              </Box>
              <Box
                gridColumn={isMobile ? "span 24" : "span 19"}
                p="4px"
                border="1px solid #ddd"
                display="flex"
                justifyContent={"space-between"}
                alignItems={"center"}
              >
                <Typography color={post.status === "종료" ? "#aaa" : null}>
                  {item.contents}
                </Typography>
                {item.savedDocName !== "" ? (
                  <DescriptionOutlinedIcon
                    sx={{
                      color: "#0000FF",
                      cursor: "pointer",
                    }}
                    onClick={() => downloadFile(item.savedDocName)}
                  />
                ) : null}
              </Box>
            </Box>
          </Box>
        </Fragment>
      ))}
      {mainUser ? null :
        <Box
          display="flex"
          justifyContent={"end"}
          alignItems={"center"}
          mt="5px"
          gap="5px"
        >
          <Box
            display="flex"
            justifyContent={"center"}
            alignItems={"center"}
            border="1px solid #5299e0"
            borderRadius={"50%"}
            backgroundColor="#dbebfb"
            p="2px"
            onClick={(e) => addSales(e)}
          >
            <AddIcon></AddIcon>
          </Box>
          <Box
            display="flex"
            justifyContent={"center"}
            alignItems={"center"}
            border="1px solid #5299e0"
            borderRadius={"50%"}
            backgroundColor="#dbebfb"
            p="2px"
            onClick={() => editSales()}
          >
            <EditIcon></EditIcon>
          </Box>
          <Box
            display="flex"
            justifyContent={"center"}
            alignItems={"center"}
            border="1px solid #5299e0"
            borderRadius={"50%"}
            p="2px"
            backgroundColor="#dbebfb"
            onClick={(e) => deleteSales(e)}
          >
            <ClearIcon></ClearIcon>
          </Box>
        </Box>
      }
    </Box>
  );
};

export default PostWidget;
