import {
  Box,
  Typography,
  Divider,
  TextField,
  Button,
  useMediaQuery,
  Radio,
  RadioGroup,
} from "@mui/material";
import WidgetWrapper from "components/WidgetWrapper";
import MenuItem from "@mui/material/MenuItem";
import FormControl from "@mui/material/FormControl";
import FormGroup from "@mui/material/FormGroup";
import FormControlLabel from "@mui/material/FormControlLabel";
import CloudUploadIcon from "@mui/icons-material/CloudUpload";
import { styled } from "@mui/material/styles";
import Checkbox from "@mui/material/Checkbox";
import { useDispatch, useSelector } from "react-redux";
import { useEffect, useRef, useState } from "react";
import { createExcelContents } from "scenes/SearchSalesPage";
import ExcelJS from "exceljs";
import { saveAs } from "file-saver";
import { setUser } from "state";

const VisuallyHiddenInput = styled("input")({
  clip: "rect(0 0 0 0)",
  clipPath: "inset(50%)",
  height: "30px",
  overflow: "hidden",
  position: "absolute",
  bottom: 0,
  left: 0,
  whiteSpace: "nowrap",
  width: 1,
});

const ReportingWidget = () => {
  const token = useSelector((state) => state.token);
  const isMobile = useMediaQuery("(max-width: 600px)");

  const user = useSelector((state) => state.user);
  const mainUser = useSelector((state) => state.mainUser);
  const dispatch = useDispatch();

  const [selectedCompanion, setSelectedCompanion] = useState({
    name: "",
    groups: [],
  });
  const [currentUser, setCurrentUser] = useState(user);
  const [groups, setGroups] = useState([]);
  const [checkedAll, setCheckedAll] = useState(false);

  const [excelFile, setExcelFile] = useState("");
  const [excelData, setExcelData] = useState([]);
  const [uploadSelectedCompanion, setUploadSelectedCompanion] = useState({
    name: "",
    groups: [],
  });
  const [uploadSelectedGroup, setUploadSelectedGroup] = useState("");
  const [uploadInputGroup, setUploadInputGroup] = useState("");
  const [where, setWhere] = useState("new");
  const [salesType, setSalesType] = useState("");

  const fileInputRef = useRef(null);

  const handleFileChange = async (event) => {
    const file = event.target.files[0];

    setExcelFile(file);

    const reader = new FileReader();

    reader.onload = async (event) => {
      const buffer = event.target.result;
      const workbook = new ExcelJS.Workbook();

      try {
        // 버퍼로부터 엑셀 파일 로드
        await workbook.xlsx.load(buffer);

        // 첫 번째 시트 가져오기
        const sheet = workbook.worksheets[0];
        // const sheet = worksheet.getWorksheet(1);
        const data = [];

        // 각 행(Row)을 순회하며 데이터 추출
        await sheet.eachRow({ includeEmpty: true }, (row, rowNumber) => {
          const rowData = [];

          // row.eachCell 에도 includeEmpty 옵션을 주어 빈 셀을 순회합니다.
          row.eachCell({ includeEmpty: true }, (cell, colNumber) => {
            rowData.push(cell.text);
          });

          data.push(rowData);
        });

        setExcelData(data);
      } catch (error) {
        console.error("엑셀 파일을 읽는 중 오류 발생:", error);
      }
    };

    // 파일을 ArrayBuffer로 읽기
    await reader.readAsArrayBuffer(file);
  };

  const uploadExcelFile = async (e) => {
    if (excelData.length === 0) {
      alert("업로드할 엑셀파일을 먼저 선택하세요");
      return;
    }

    if (uploadSelectedCompanion.name === "") {
      alert("공동영업자를 먼저 선택하세요.");
      return;
    }

    if (where === "new") {
      if (uploadInputGroup === "") {
        alert("새로 생성할 그룹명을 입력하세요.");
        return;
      }
    } else if (where === "exist") {
      if (uploadSelectedGroup === "") {
        alert("기존의 그룹을 선택하세요");
        return;
      }
    }

    try {
      if (where === "new") {
        const updatedComcompanions = currentUser.companion.map((value) => {
          if (value.name === uploadSelectedCompanion.name) {
            if (value.groups.includes(uploadInputGroup)) {
              throw new Error(`그룹 '${uploadInputGroup}'는 이미 존재합니다.`);
            }
            return {
              ...value,
              groups: [...(value.groups || []), uploadInputGroup],
            };
          }
          return value;
        });

        const updatedUser = {
          ...currentUser,
          companion: updatedComcompanions,
        };

        dispatch(setUser(updatedUser));
        setCurrentUser(updatedUser);
      }

      const response = await fetch(
        `http://3.37.116.103:3500/data/uploadCompanies`,
        {
          method: "POST",
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            userId: currentUser._id,
            data: excelData,
            mode: where,
            companion: uploadSelectedCompanion.name,
            group: where === "new" ? uploadInputGroup : uploadSelectedGroup,
            salesType: salesType,
          }),
        },
      );

      if (!response.ok) {
        const error = await response.json();
        alert(error);
        return;
      }

      setSelectedCompanion({ name: "", groups: [] });
      setUploadSelectedCompanion({ name: "", groups: [] });
      setUploadInputGroup("");
      setGroups([]);
      setCheckedAll(false);
      setWhere("new");
      setExcelFile("");

      if (fileInputRef.current) {
        fileInputRef.current.value = "";
      }

      alert("엑셀파일이 업로드 되었습니다.");
    } catch (error) {
      alert(error);
    }
  };

  const createReport = async (e) => {
    if (selectedCompanion.name === "") {
      alert("공동영업 항목을 선택해 주세요.");
      return;
    }

    const response = await fetch(`http://3.37.116.103:3500/data/createReport`, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${token}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        userId: user._id,
        userName: user.name,
        companion: selectedCompanion.name,
        mainUser: mainUser
      }),
    });

    if (!response.ok) {
      const error = await response.json();
      alert(error);
      return;
    }

    const data = await response.json();

    if (data.length === 0) {
      alert("엑셀 파일을 생성할 data가 없습니다.");
      return;
    }

    const workbook = new ExcelJS.Workbook();

    await data.forEach((group) => {
      const exist = groups.find((item) => {
        return item.group === group._id;
      });
      if (exist.selected) {
        createExcelContents(workbook, group._id, group.documents.reverse());
      }
    });

    if (workbook.worksheets.length === 0) {
      alert("엑셀 파일을 생성할 data가 없습니다.");
      return;
    }
    const buffer = await workbook.xlsx.writeBuffer();
    const blob = new Blob([buffer], {
      type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
    });

    const now = new Date();

    const year = now.getFullYear();
    const month = String(now.getMonth() + 1).padStart(2, "0");
    const day = String(now.getDate()).padStart(2, "0");

    const formattedDateTime = `${year}${month}${day}_`;

    saveAs(
      blob,
      formattedDateTime + `${selectedCompanion.name}_sales_data.xlsx`,
    );

    alert("엑셀파일이 생성되었습니다");
  };

  const selectCompanion = (e) => {
    const who = user.companion.find((u) => u.name === e.target.value);
    setSelectedCompanion(who);
    const groups = who.groups.map((item) => {
      return { group: item, selected: false };
    });
    setGroups([...groups]);
  };

  const uploadSelectCompanion = (e) => {
    const who = user.companion.find((u) => u.name === e.target.value);
    setUploadSelectedCompanion(who);
  };

  const handleCheckChange = (group, e) => {
    const updated = groups.map((value) =>
      value.group === group ? { ...value, selected: e.target.checked } : value,
    );
    setGroups([...updated]);

    const all = updated.every((value) => value.selected === true);

    if (all) setCheckedAll(true);
    else setCheckedAll(false);
  };

  const handleCheckedAll = (e) => {
    setCheckedAll(e.target.checked);

    const updated = groups.map((value) => {
      value.selected = e.target.checked;
      return value;
    });
    setGroups([...updated]);
  };

  useEffect(() => {
    if (mainUser) {
      const who = mainUser.companion.find((u) => u.name === user.name);
      setSelectedCompanion(who);
      const groups = who.groups.map((item) => {
        return { group: item, selected: false };
      });
      setGroups([...groups]);
    }
  }, [mainUser, user.name])

  return (
    <WidgetWrapper>
      <Typography
        mb={mainUser ? "" : "40px"}
        sx={{ fontSize: "18px", fontWeight: 600 }}
      >
        유틸리티
      </Typography>
      {mainUser ? 
        <Typography
          mb={"30px"}
          sx={{ fontSize: "14px", color: "#FF0000"}}
        >
          (현재 {mainUser.name}님의 동행자 모드입니다)
        </Typography>
      : null }
      <Box display="grid" gridTemplateColumns={"1fr"} gap="20px">
        {/* FIRST ROW */}
        <Typography
          mb="10px"
          sx={{
            fontSize: "16px",
            fontWeight: 600,
            color: "#999",
          }}
        >
          영업자료 생성
        </Typography>
        <Box
          display={isMobile ? "block" : "flex"}
          justifyContent={"space-between"}
          gap="1.5rem"
          pb="1.1rem"
        >
          <Box gap="1.5rem">
            <Box display="grid" gap="20px">
              <Box>
                <TextField
                  disabled={mainUser ? true : false}
                  select={mainUser ? false : true}
                  label="공동영업"
                  name="companion"
                  value={mainUser ? user.name : selectedCompanion.name}
                  onChange={(e) => selectCompanion(e)}
                  sx={{ width: isMobile ? "100%" : "220px" }}
                >
                  {user.companion.map((item) => (
                    <MenuItem value={item.name}>{item.name}</MenuItem>
                  ))}
                </TextField>
              </Box>
              <Box
                display="grid"
                gridTemplateColumns={isMobile ? "1fr" : "1fr 1fr"}
                gap="20px"
              >
                <Box
                  sx={{
                    width: isMobile ? "100%" : "220px",
                    maxHeight: "400px",
                    overflowY: "auto",
                    backgroundColor: "#f4f4f4",
                    border: "1px solid #ddd",
                    borderRadius: "7px",
                    padding: "15px 20px",
                    order: isMobile ? 2 : 1,
                  }}
                >
                  <FormControl
                    width="100%"
                    component="fieldset"
                    variant="standard"
                  >
                    <FormGroup>
                      {groups.map((item, index) => (
                        <FormControlLabel
                          control={
                            <Checkbox
                              checked={item.selected}
                              onChange={(e) => handleCheckChange(item.group, e)}
                              name={item.group}
                            />
                          }
                          label={item.group}
                        />
                      ))}
                    </FormGroup>
                  </FormControl>
                </Box>
                <FormControl
                  width="100%"
                  component="fieldset"
                  variant="standard"
                  sx={{ order: isMobile ? 1 : 2 }}
                >
                  <FormGroup>
                    <FormControlLabel
                      control={
                        <Checkbox
                          checked={checkedAll}
                          onChange={(e) => handleCheckedAll(e)}
                          name={"checkedAll"}
                        />
                      }
                      label="전체"
                    />
                  </FormGroup>
                </FormControl>
              </Box>
            </Box>
          </Box>
          <Box>
            <Button
              sx={{
                mt: isMobile ? "20px" : "0",
                mr: "15px",
                p: "1rem",
                backgroundColor: "#0073E6",
                color: "#fff",
                "&:hover": { backgroundColor: "#5299e0" },
              }}
              onClick={() => createReport()}
            >
              Report 생성
            </Button>
            <Button
              sx={{
                mt: isMobile ? "20px" : "0",
                p: "1rem",
                backgroundColor: "#0073E6",
                color: "#fff",
                "&:hover": { backgroundColor: "#5299e0" },
              }}
              onClick={() => {
                setSelectedCompanion({ name: "", groups: [] });
                setCurrentUser(user);
                setGroups([]);
                setCheckedAll(false);
              }}
            >
              초기화
            </Button>
          </Box>
        </Box>
      </Box>
      <Divider />
      <Box>
        <Typography
          m="40px 0"
          sx={{
            fontSize: "16px",
            fontWeight: 600,
            color: "#999",
          }}
        >
          업체정보 Upload
        </Typography>
        <Box
          gap="1.5rem"
          pb="1.1rem"
          display={isMobile ? "block" : "flex"}
          justifyContent={"space-between"}
        >
          <Box>
            <Button
              disabled={mainUser ? true : false }
              component="label"
              variant="contained"
              startIcon={<CloudUploadIcon />}
              sx={{
                height: "50px",
                mb: "15px",
                backgroundColor: "#097509"
              }}
            >
              Upload Files
              <VisuallyHiddenInput
                type="file"
                ref={fileInputRef}
                onInput={handleFileChange}
                accept=".xlsx, .xls, application/vnd.openxmlformats-officedocument.spreadsheetml.sheet, application/vnd.ms-excel" 
              />
            </Button>
            {excelFile.name && (
              <Typography
                sx={{ marginBottom: "15px" }}
                variant="body2"
                color="textSecondary"
              >
                Selected: {excelFile.name}
              </Typography>
            )}
            <Box display="flex" flexDirection={"column"} gap="15px">
              <Box mb={isMobile ? "20px" : "0"}>
                <TextField
                  disabled={mainUser ? true : false }
                  select
                  label="공동영업자"
                  name="companion"
                  value={uploadSelectedCompanion.name}
                  onChange={(e) => uploadSelectCompanion(e)}
                  sx={{ width: isMobile ? "100%" : "220px" }}
                >
                  {user.companion.map((item) => (
                    <MenuItem value={item.name}>{item.name}</MenuItem>
                  ))}
                </TextField>
              </Box>
              <Box
                display={isMobile ? "block" : "flex"}
                mb={isMobile ? "20px" : "0"}
              >
                <FormControl>
                  <RadioGroup
                    row
                    name="where"
                    value={where}
                    onChange={(e) => setWhere(e.target.value)}
                  >
                    <FormControlLabel
                      disabled={mainUser ? true : false }
                      label="새그룹 생성"
                      value="new"
                      control={
                        <Radio
                          sx={{
                            color: "#79058e",
                            "&.Mui-checked": {
                              color: "#79058e",
                            },
                          }}
                        />
                      }
                    />
                    <FormControlLabel
                      disabled={mainUser ? true : false }
                      label="기존그룹에 추가"
                      value="exist"
                      control={
                        <Radio
                          sx={{
                            color: "#79058e",
                            "&.Mui-checked": {
                              color: "#79058e",
                            },
                          }}
                        />
                      }
                    />
                  </RadioGroup>
                </FormControl>
              </Box>
              <TextField
                disabled={mainUser ? true : false }
                select={where === "exist" ? true : false}
                label="그룹"
                name="uploadGroup"
                value={
                  where === "exist" ? uploadSelectedGroup : uploadInputGroup
                }
                onChange={
                  where === "exist"
                    ? (e) => setUploadSelectedGroup(e.target.value)
                    : (e) => setUploadInputGroup(e.target.value)
                }
                sx={{ width: isMobile ? "100%" : "220px" }}
              >
                {where === "exist" &&
                  uploadSelectedCompanion.groups.map((item) => (
                    <MenuItem value={item}>{item}</MenuItem>
                  ))}
              </TextField>
              <FormControl sx={{ width: isMobile ? "100%" : "220px" }}>
                <TextField
                  disabled={mainUser ? true : false }
                  select
                  label="영업유형"
                  name="salesType"
                  value={salesType}
                  onChange={(e) => setSalesType(e.target.value)}
                >
                  <MenuItem value={"개척"}>개척</MenuItem>
                  <MenuItem value={"타겟"}>타겟</MenuItem>
                  <MenuItem value={"TA"}>TA</MenuItem>
                  <MenuItem value={"소개"}>소개</MenuItem>
                </TextField>
              </FormControl>
            </Box>
          </Box>
          <Box>
            <Button
              disabled={mainUser ? true : false }
              sx={{
                mt: isMobile ? "20px" : "0",
                mr: "15px",
                p: "1rem",
                backgroundColor: "#0073E6",
                color: "#fff",
                "&:hover": { backgroundColor: "#5299e0" },
              }}
              onClick={(e) => uploadExcelFile(e)}
            >
              File Upload
            </Button>
            <Button
              disabled={mainUser ? true : false }
              sx={{
                mt: isMobile ? "20px" : "0",
                p: "1rem",
                backgroundColor: "#0073E6",
                color: "#fff",
                "&:hover": { backgroundColor: "#5299e0" },
              }}
              onClick={(e) => {
                setExcelFile("");
                setExcelData([]);
                setUploadSelectedCompanion({ name: "", groups: [] });
                setUploadSelectedGroup("");
                setUploadInputGroup("");
                setWhere("new");
              }}
            >
              초기화
            </Button>
          </Box>
        </Box>
      </Box>
    </WidgetWrapper>
  );
};

export default ReportingWidget;
