import { Box, useMediaQuery } from "@mui/material";
import { useSelector, useDispatch } from "react-redux";
import ReportingWidget from "scenes/widgets/ReportingWidget";
import RegistCompanyWidget from "scenes/widgets/RegistCompanyWidget";
import { setEditData } from "state";
import WidgetWrapper from "components/WidgetWrapper";

const MyPage = () => {
  const isNonMobileScreens = useMediaQuery("(min-width:1000px)");
  const { _id, picturePath } = useSelector((state) => state.user);
  const dispatch = useDispatch()

  dispatch(setEditData(null))
  
  return (
    <Box
      mt="80px"
      width="100%"
      padding="1rem 1.5rem"
      display={isNonMobileScreens ? "flex" : "block"}
      gap="1.5rem"
      justifyContent="center"
    >
      <Box flexBasis={isNonMobileScreens ? "70%" : undefined}>
          <ReportingWidget userId={_id} picturePath={picturePath}/>
      </Box>
    </Box>
  );
};

export default MyPage;
